import java.util.*;import java.nio.file.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
 static String B="mod/cdv/tnpc/tactical/",H=B+"Roles22";static Map<String,Integer>hits=new TreeMap<>();
 static void hit(String s){hits.merge(s,1,Integer::sum);}static MethodInsnNode call(String name,String desc){return new MethodInsnNode(INVOKESTATIC,H,name,desc,false);}
 static void predicate(MethodNode m,String method,int slot,int opcode,int value){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,slot));l.add(call(method,"(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));if(opcode!=RETURN)l.add(new InsnNode(value));l.add(new InsnNode(opcode));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);}
 static byte[]patch(String file,byte[]bytes){ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);
 for(MethodNode m:c.methods){String key=c.name.substring(c.name.lastIndexOf('/')+1)+"."+m.name;
 if(c.name.equals("mod/cdv/tnpc/entity/AutoGunOperator")&&(m.name.equals("readAdditionalSaveData")||m.name.equals("addAdditionalSaveData"))){if(m.name.equals("readAdditionalSaveData")){InsnList l=new InsnList();l.add(new VarInsnNode(ALOAD,0));l.add(new VarInsnNode(ALOAD,1));l.add(call("read","(Ljava/lang/Object;Ljava/lang/Object;)V"));m.instructions.insert(l);}for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList l=new InsnList();l.add(new VarInsnNode(ALOAD,0));if(m.name.equals("readAdditionalSaveData"))l.add(call("finish","(Ljava/lang/Object;)V"));else{l.add(new VarInsnNode(ALOAD,1));l.add(call("write","(Ljava/lang/Object;Ljava/lang/Object;)V"));}m.instructions.insertBefore(n,l);}hit(key);}
 if(c.name.equals(B+"Social")){
 if(m.name.equals("init")){for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList l=new InsnList();l.add(new VarInsnNode(ALOAD,0));l.add(call("kind","(Ljava/lang/Object;)V"));m.instructions.insertBefore(n,l);}hit(key);}
 if(m.name.equals("tick")){InsnList l=new InsnList();l.add(new VarInsnNode(ALOAD,0));l.add(call("socialTick","(Ljava/lang/Object;)V"));m.instructions.insert(l);hit(key);}
 if(m.name.equals("acquire")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,0));l.add(new VarInsnNode(ALOAD,1));l.add(new VarInsnNode(LLOAD,2));l.add(new VarInsnNode(ILOAD,4));l.add(call("acquire","(Ljava/lang/Object;Ljava/lang/Object;JZ)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new InsnNode(RETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(m.name.equals("allowedPlayer")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,0));l.add(call("hostile","(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new VarInsnNode(ALOAD,0));l.add(new VarInsnNode(ALOAD,1));l.add(call("allowed","(Ljava/lang/Object;Ljava/lang/Object;)Z"));l.add(new InsnNode(IRETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(m.name.equals("orders")||m.name.equals("environment")){predicate(m,m.name.equals("orders")?"autonomous":"military",0,RETURN,0);hit(key);}}
 if(c.name.equals(B+"StarterGear")){
 if(m.name.equals("outfit")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,0));l.add(new VarInsnNode(ALOAD,1));l.add(call("gear","(Ljava/lang/Object;Ljava/util/Random;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new InsnNode(RETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(m.name.equals("tick")||m.name.equals("reload")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,0));l.add(call("military","(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new VarInsnNode(ALOAD,0));l.add(call(m.name.equals("tick")?"reloadTick":"reload",m.name.equals("tick")?"(Ljava/lang/Object;)V":"(Ljava/lang/Object;)Z"));l.add(new InsnNode(m.name.equals("tick")?RETURN:IRETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(m.name.equals("ammunition")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,1));l.add(call("military","(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new IntInsnNode(SIPUSH,10000));l.add(new InsnNode(IRETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}}
 if(c.name.equals(B+"TeamBrain")&&m.name.equals("playerAim")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,1));l.add(call("military","(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new VarInsnNode(ALOAD,0));l.add(new InsnNode(ARETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(c.name.equals(B+"VanillaGunGoal")&&m.name.equals("tick")){InsnList l=new InsnList();LabelNode next=new LabelNode();l.add(new VarInsnNode(ALOAD,0));l.add(new FieldInsnNode(GETFIELD,c.name,"mob","Ljava/lang/Object;"));l.add(call("combat","(Ljava/lang/Object;)Z"));l.add(new JumpInsnNode(IFEQ,next));l.add(new InsnNode(RETURN));l.add(next);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);hit(key);}
 if(c.name.equals(B+"CalmLoot")&&m.name.equals("tier")){predicate(m,"military",0,IRETURN,ICONST_3);hit(key);}
 }
 ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);byte[]out=w.toByteArray();ClassNode check=new ClassNode();new ClassReader(out).accept(check,0);for(MethodNode m:check.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)try{new Analyzer<BasicValue>(new BasicVerifier()).analyze(check.name,m);}catch(Exception e){throw new RuntimeException(file+"."+m.name,e);}return out;
 }
 public static void main(String[]args)throws Exception{Map<String,byte[]>e=new TreeMap<>();Set<String>targets=Set.of("mod/cdv/tnpc/entity/AutoGunOperator.class",B+"Social.class",B+"StarterGear.class",B+"TeamBrain.class",B+"VanillaGunGoal.class",B+"CalmLoot.class");try(ZipFile z=new ZipFile(args[0])){for(ZipEntry n:Collections.list(z.entries())){byte[]b=z.getInputStream(n).readAllBytes();if(targets.contains(n.getName()))b=patch(n.getName(),b);e.put(n.getName(),b);}}
 Set<String>expected=Set.of("AutoGunOperator.readAdditionalSaveData","AutoGunOperator.addAdditionalSaveData","Social.init","Social.tick","Social.acquire","Social.allowedPlayer","Social.orders","Social.environment","StarterGear.outfit","StarterGear.tick","StarterGear.reload","StarterGear.ammunition","TeamBrain.playerAim","VanillaGunGoal.tick","CalmLoot.tier");if(!hits.keySet().equals(expected)||hits.values().stream().anyMatch(i->i!=1))throw new AssertionError(hits);
 try(var fs=Files.walk(Path.of(args[2]))){for(Path p:fs.filter(p->p.toString().endsWith(".class")).toList())e.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var n:e.entrySet()){ZipEntry ze=new ZipEntry(n.getKey());ze.setTime(0);z.putNextEntry(ze);z.write(n.getValue());z.closeEntry();}}System.out.println("NPC22_NATIVE_METHOD_HOOKS_BYTECODE_VERIFIED="+hits.size());}
}
